from openai import OpenAI

def get_image_description(image_url: str) -> str:
    """
    Generates a short visual description for an image.
    """
    client = OpenAI() # Assumes OPENAI_API_KEY environment variable is set

    response = client.chat.completions.create(
        model="gpt-4o", # Using a multi-modal model
        messages=[
            {
                "role": "user",
                "content": [
                    {"type": "text", "text": "What's in this image? Provide a concise description."},
                    {
                        "type": "image_url",
                        "image_url": {
                            "url": image_url,
                        },
                    },
                ],
            }
        ],
        max_tokens=100, # Limit the length of the description
    )
    return response.choices[0].message.content
